-- Module 22: delivery lifecycle, proof, and courier integration boundary.
update public.module_definitions set configuration_schema='{"properties":{"require_proof_of_delivery":{"type":"boolean","label":"Require proof before delivery completion","default":false},"default_courier_provider":{"type":"string","label":"Default courier provider key","minLength":1,"maxLength":64,"default":"internal"}},"additionalProperties":false}'::jsonb,updated_at=now()where key='delivery';
insert into public.permissions(key,domain,action,description)values('delivery.read','delivery','read','View deliveries'),('delivery.manage','delivery','manage','Create deliveries'),('delivery.assign','delivery','assign','Assign delivery drivers'),('delivery.status','delivery','status','Update delivery status'),('delivery.proof','delivery','proof','Upload proof of delivery')on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_delivery_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and permission.key like'delivery.%'on conflict do nothing;insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(case role.key when'staff'then array['delivery.read','delivery.status','delivery.proof']when'viewer'then array['delivery.read']else array[]::text[]end)where role.organization_id=requested_organization_id and role.key in('staff','viewer')on conflict do nothing;end;$$;
create function private.handle_main_branch_delivery_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_delivery_permissions(new.organization_id);end if;return new;end;$$;create trigger zzzzzzzzz_install_delivery_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_delivery_permissions();select private.install_delivery_permissions(id)from public.organizations;

create table public.delivery_drivers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,membership_id uuid not null,user_id uuid not null references auth.users(id)on delete restrict,display_name text not null check(char_length(btrim(display_name))between 1 and 160),status text not null default'active'check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,membership_id),foreign key(membership_id,organization_id)references public.organization_memberships(id,organization_id)on delete cascade);
create table public.delivery_counters(organization_id uuid primary key references public.organizations(id)on delete cascade,next_value bigint not null default 1 check(next_value>0));
create table public.deliveries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,source_branch_id uuid not null,delivery_number text not null,customer_id uuid not null,delivery_address text not null check(char_length(btrim(delivery_address))between 1 and 1000),contact_number text not null check(char_length(btrim(contact_number))between 1 and 40),related_transaction_id uuid,assigned_driver_id uuid,vehicle text check(char_length(vehicle)<=160),scheduled_at timestamptz not null,status text not null default'pending'check(status in('pending','scheduled','assigned','out_for_delivery','delivered','failed','cancelled')),courier_provider text not null default'internal'check(courier_provider~'^[a-z][a-z0-9_-]{0,63}$'),external_reference text,courier_metadata jsonb not null default'{}'check(jsonb_typeof(courier_metadata)='object'),delivered_at timestamptz,failure_reason text check(char_length(failure_reason)<=1000),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,delivery_number),foreign key(source_branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete restrict,foreign key(related_transaction_id,organization_id)references public.sales_transactions(id,organization_id)on delete restrict,foreign key(assigned_driver_id,organization_id)references public.delivery_drivers(id,organization_id)on delete restrict
);
create table public.delivery_status_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null,delivery_id uuid not null,from_status text,to_status text not null,notes text check(char_length(notes)<=1000),actor_id uuid not null references auth.users(id),occurred_at timestamptz not null default now(),foreign key(delivery_id,organization_id)references public.deliveries(id,organization_id)on delete cascade);
create table public.delivery_proofs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,delivery_id uuid not null,path text not null,file_name text not null check(char_length(file_name)between 1 and 255),mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 10485760),notes text check(char_length(notes)<=500),uploaded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,path),foreign key(delivery_id,organization_id)references public.deliveries(id,organization_id)on delete cascade);
create index delivery_queue_idx on public.deliveries(organization_id,source_branch_id,status,scheduled_at);create index delivery_driver_idx on public.deliveries(assigned_driver_id,status,scheduled_at)where assigned_driver_id is not null;create index delivery_customer_idx on public.deliveries(customer_id,created_at desc);create index delivery_history_idx on public.delivery_status_history(delivery_id,occurred_at desc);create index delivery_proof_idx on public.delivery_proofs(delivery_id,created_at desc);
create trigger set_updated_at before update on public.delivery_drivers for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.deliveries for each row execute function private.set_updated_at();
insert into public.delivery_drivers(organization_id,membership_id,user_id,display_name)select membership.organization_id,membership.id,membership.user_id,coalesce(nullif(btrim(profile.display_name),''),split_part(user_record.email,'@',1),'Driver')from public.organization_memberships membership join auth.users user_record on user_record.id=membership.user_id left join public.profiles profile on profile.id=membership.user_id where membership.status='active'on conflict(organization_id,membership_id)do nothing;
create function private.sync_delivery_driver_membership()returns trigger language plpgsql security definer set search_path='' as $$declare name_value text;begin select coalesce(nullif(btrim(profile.display_name),''),split_part(user_record.email,'@',1),'Driver')into name_value from auth.users user_record left join public.profiles profile on profile.id=user_record.id where user_record.id=new.user_id;insert into public.delivery_drivers(organization_id,membership_id,user_id,display_name,status)values(new.organization_id,new.id,new.user_id,name_value,case when new.status='active'then'active'else'inactive'end)on conflict(organization_id,membership_id)do update set display_name=excluded.display_name,status=excluded.status;return new;end;$$;create trigger sync_delivery_driver after insert or update of status on public.organization_memberships for each row execute function private.sync_delivery_driver_membership();

create function private.delivery_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='delivery');$$;
create function private.delivery_config(requested_organization_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(module.config,'{}')from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='delivery';$$;
create function private.next_delivery_number(requested_organization_id uuid)returns text language plpgsql security definer set search_path='' as $$declare value bigint;begin insert into public.delivery_counters(organization_id,next_value)values(requested_organization_id,2)on conflict(organization_id)do update set next_value=public.delivery_counters.next_value+1 returning next_value-1 into value;if value is null then value:=1;end if;return'DEL-'||extract(year from current_date)::integer||'-'||lpad(value::text,6,'0');end;$$;
create function private.can_read_delivery(requested_organization_id uuid,requested_delivery_id uuid)returns boolean language sql stable security definer set search_path='' as $$select private.delivery_module_enabled(requested_organization_id)and exists(select 1 from public.deliveries delivery where delivery.id=requested_delivery_id and delivery.organization_id=requested_organization_id and private.can_business_permission(requested_organization_id,'delivery.read',delivery.source_branch_id));$$;

create function private.save_delivery(requested_organization_id uuid,requested_source_branch_id uuid,requested_customer_id uuid,requested_address text,requested_contact text,requested_transaction_id uuid,requested_scheduled_at timestamptz,requested_vehicle text,requested_courier_provider text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());target_id uuid:=gen_random_uuid();number text;provider text;begin if actor is null or not private.delivery_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'delivery.manage',requested_source_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;provider:=coalesce(nullif(btrim(requested_courier_provider),''),private.delivery_config(requested_organization_id)->>'default_courier_provider','internal');if char_length(btrim(requested_address))not between 1 and 1000 or char_length(btrim(requested_contact))not between 1 and 40 or char_length(coalesce(requested_vehicle,''))>160 or provider!~'^[a-z][a-z0-9_-]{0,63}$'or not exists(select 1 from public.branches where id=requested_source_branch_id and organization_id=requested_organization_id and is_active)or not exists(select 1 from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id)or(requested_transaction_id is not null and not exists(select 1 from public.sales_transactions where id=requested_transaction_id and organization_id=requested_organization_id and customer_id=requested_customer_id))then raise exception'Invalid delivery.'using errcode='22023';end if;number:=private.next_delivery_number(requested_organization_id);insert into public.deliveries(id,organization_id,source_branch_id,delivery_number,customer_id,delivery_address,contact_number,related_transaction_id,vehicle,scheduled_at,courier_provider,created_by,updated_by)values(target_id,requested_organization_id,requested_source_branch_id,number,requested_customer_id,btrim(requested_address),btrim(requested_contact),requested_transaction_id,nullif(btrim(requested_vehicle),''),requested_scheduled_at,provider,actor,actor);insert into public.delivery_status_history(organization_id,delivery_id,to_status,actor_id,notes)values(requested_organization_id,target_id,'pending',actor,'Delivery created');return target_id;end;$$;
create function private.assign_delivery_driver(requested_organization_id uuid,requested_delivery_id uuid,requested_driver_id uuid,requested_vehicle text)returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());delivery public.deliveries%rowtype;begin select*into delivery from public.deliveries where id=requested_delivery_id and organization_id=requested_organization_id for update;if actor is null or delivery.id is null or not private.delivery_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'delivery.assign',delivery.source_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if delivery.status not in('scheduled','failed','assigned')or not exists(select 1 from public.delivery_drivers where id=requested_driver_id and organization_id=requested_organization_id and status='active')or char_length(coalesce(requested_vehicle,''))>160 then raise exception'Invalid driver assignment.'using errcode='P0001';end if;update public.deliveries set assigned_driver_id=requested_driver_id,vehicle=coalesce(nullif(btrim(requested_vehicle),''),vehicle),status='assigned',updated_by=actor where id=delivery.id;insert into public.delivery_status_history(organization_id,delivery_id,from_status,to_status,actor_id,notes)values(requested_organization_id,delivery.id,delivery.status,'assigned',actor,'Driver assigned');end;$$;
create function private.change_delivery_status(requested_organization_id uuid,requested_delivery_id uuid,requested_status text,requested_notes text)returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());delivery public.deliveries%rowtype;allowed boolean;require_proof boolean;begin select*into delivery from public.deliveries where id=requested_delivery_id and organization_id=requested_organization_id for update;if actor is null or delivery.id is null or not private.delivery_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'delivery.status',delivery.source_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;allowed:=case delivery.status when'pending'then requested_status in('scheduled','cancelled')when'scheduled'then requested_status in('cancelled')when'assigned'then requested_status in('out_for_delivery','scheduled','cancelled')when'out_for_delivery'then requested_status in('delivered','failed')when'failed'then requested_status in('cancelled')else false end;require_proof:=coalesce((private.delivery_config(requested_organization_id)->>'require_proof_of_delivery')::boolean,false);if not allowed or char_length(coalesce(requested_notes,''))>1000 or(requested_status='scheduled'and delivery.scheduled_at is null)or(requested_status='out_for_delivery'and delivery.assigned_driver_id is null)or(requested_status='delivered'and require_proof and not exists(select 1 from public.delivery_proofs where delivery_id=delivery.id))then raise exception'Invalid delivery status transition.'using errcode='P0001';end if;update public.deliveries set status=requested_status,delivered_at=case when requested_status='delivered'then now()else delivered_at end,failure_reason=case when requested_status='failed'then nullif(btrim(requested_notes),'')else failure_reason end,updated_by=actor where id=delivery.id;insert into public.delivery_status_history(organization_id,delivery_id,from_status,to_status,notes,actor_id)values(requested_organization_id,delivery.id,delivery.status,requested_status,nullif(btrim(requested_notes),''),actor);end;$$;
create function private.attach_delivery_proof(requested_organization_id uuid,requested_delivery_id uuid,requested_path text,requested_file_name text,requested_mime_type text,requested_size bigint,requested_notes text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());delivery public.deliveries%rowtype;target_id uuid;begin select*into delivery from public.deliveries where id=requested_delivery_id and organization_id=requested_organization_id;if actor is null or delivery.id is null or not private.delivery_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'delivery.proof',delivery.source_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if delivery.status in('pending','cancelled')or requested_path not like requested_organization_id||'/'||delivery.id||'/%'or requested_mime_type not in('image/jpeg','image/png','image/webp','application/pdf')or requested_size not between 1 and 10485760 or char_length(requested_file_name)not between 1 and 255 or char_length(coalesce(requested_notes,''))>500 then raise exception'Invalid proof of delivery.'using errcode='22023';end if;insert into public.delivery_proofs(organization_id,delivery_id,path,file_name,mime_type,size_bytes,notes,uploaded_by)values(requested_organization_id,delivery.id,requested_path,requested_file_name,requested_mime_type,requested_size,nullif(btrim(requested_notes),''),actor)returning id into target_id;return target_id;end;$$;
create function private.can_access_delivery_proof(requested_path text,requested_permission text)returns boolean language plpgsql stable security definer set search_path='' as $$declare organization_value uuid;delivery_value uuid;branch_value uuid;begin organization_value:=split_part(requested_path,'/',1)::uuid;delivery_value:=split_part(requested_path,'/',2)::uuid;select source_branch_id into branch_value from public.deliveries where id=delivery_value and organization_id=organization_value;return branch_value is not null and private.delivery_module_enabled(organization_value)and private.can_business_permission(organization_value,requested_permission,branch_value);exception when invalid_text_representation then return false;end;$$;

create function public.save_delivery(requested_organization_id uuid,requested_source_branch_id uuid,requested_customer_id uuid,requested_address text,requested_contact text,requested_transaction_id uuid,requested_scheduled_at timestamptz,requested_vehicle text,requested_courier_provider text)returns uuid language sql security definer set search_path='' as $$select private.save_delivery(requested_organization_id,requested_source_branch_id,requested_customer_id,requested_address,requested_contact,requested_transaction_id,requested_scheduled_at,requested_vehicle,requested_courier_provider);$$;
create function public.assign_delivery_driver(requested_organization_id uuid,requested_delivery_id uuid,requested_driver_id uuid,requested_vehicle text)returns void language sql security definer set search_path='' as $$select private.assign_delivery_driver(requested_organization_id,requested_delivery_id,requested_driver_id,requested_vehicle);$$;create function public.change_delivery_status(requested_organization_id uuid,requested_delivery_id uuid,requested_status text,requested_notes text)returns void language sql security definer set search_path='' as $$select private.change_delivery_status(requested_organization_id,requested_delivery_id,requested_status,requested_notes);$$;create function public.attach_delivery_proof(requested_organization_id uuid,requested_delivery_id uuid,requested_path text,requested_file_name text,requested_mime_type text,requested_size bigint,requested_notes text)returns uuid language sql security definer set search_path='' as $$select private.attach_delivery_proof(requested_organization_id,requested_delivery_id,requested_path,requested_file_name,requested_mime_type,requested_size,requested_notes);$$;

alter table public.delivery_drivers enable row level security;alter table public.deliveries enable row level security;alter table public.delivery_status_history enable row level security;alter table public.delivery_proofs enable row level security;
create policy delivery_drivers_read on public.delivery_drivers for select to authenticated using((select private.delivery_module_enabled(organization_id))and private.can_business_permission(organization_id,'delivery.read',null));create policy deliveries_read on public.deliveries for select to authenticated using((select private.delivery_module_enabled(organization_id))and private.can_business_permission(organization_id,'delivery.read',source_branch_id));create policy delivery_history_read on public.delivery_status_history for select to authenticated using((select private.can_read_delivery(organization_id,delivery_id)));create policy delivery_proofs_read on public.delivery_proofs for select to authenticated using((select private.can_read_delivery(organization_id,delivery_id)));
revoke all on table public.delivery_drivers,public.delivery_counters,public.deliveries,public.delivery_status_history,public.delivery_proofs from public,anon,authenticated;grant select on table public.delivery_drivers,public.deliveries,public.delivery_status_history,public.delivery_proofs to authenticated;
revoke all on function private.install_delivery_permissions(uuid),private.handle_main_branch_delivery_permissions(),private.sync_delivery_driver_membership(),private.delivery_module_enabled(uuid),private.delivery_config(uuid),private.next_delivery_number(uuid),private.can_read_delivery(uuid,uuid),private.save_delivery(uuid,uuid,uuid,text,text,uuid,timestamptz,text,text),private.assign_delivery_driver(uuid,uuid,uuid,text),private.change_delivery_status(uuid,uuid,text,text),private.attach_delivery_proof(uuid,uuid,text,text,text,bigint,text),private.can_access_delivery_proof(text,text)from public,anon,authenticated;grant execute on function private.delivery_module_enabled(uuid),private.can_read_delivery(uuid,uuid),private.can_access_delivery_proof(text,text)to authenticated;
revoke all on function public.save_delivery(uuid,uuid,uuid,text,text,uuid,timestamptz,text,text),public.assign_delivery_driver(uuid,uuid,uuid,text),public.change_delivery_status(uuid,uuid,text,text),public.attach_delivery_proof(uuid,uuid,text,text,text,bigint,text)from public,anon;grant execute on function public.save_delivery(uuid,uuid,uuid,text,text,uuid,timestamptz,text,text),public.assign_delivery_driver(uuid,uuid,uuid,text),public.change_delivery_status(uuid,uuid,text,text),public.attach_delivery_proof(uuid,uuid,text,text,text,bigint,text)to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('delivery-proofs','delivery-proofs',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy delivery_proof_select on storage.objects for select to authenticated using(bucket_id='delivery-proofs'and private.can_access_delivery_proof(name,'delivery.read'));create policy delivery_proof_insert on storage.objects for insert to authenticated with check(bucket_id='delivery-proofs'and private.can_access_delivery_proof(name,'delivery.proof'));create policy delivery_proof_delete on storage.objects for delete to authenticated using(bucket_id='delivery-proofs'and private.can_access_delivery_proof(name,'delivery.proof'));
comment on column public.deliveries.courier_provider is'Stable provider key for a future third-party courier adapter; internal means NegosyoOS-managed delivery.';
